{"issue": true, "summary": "When a mapper function fails during iteration, the queue's pending items are not properly rejected, leading to orphaned rejections that cause validation failures.", "edits": [{"path": "index.js", "old": "while (queue.size > 0) {
					queue.dequeue().reject(abortError);
				}", "new": "while (queue.size > 0) {
					const item = queue.dequeue();
					if (typeof item.reject === 'function') {
						item.reject(abortError);
					}
				}"}]}
